package local.skyfamily;
import android.content.Context;import android.os.Build;import android.util.Base64;import java.security.*;import java.util.*;import javax.crypto.*;import javax.crypto.spec.*;import org.json.*;
final class SessionVault {
 static final String ALIAS="sky-family-immich-v1";
 static String b64(byte[] b){return Base64.encodeToString(b,Base64.NO_WRAP);}static byte[] bytes(JSONObject j,String k)throws Exception{return Base64.decode(j.getString(k),Base64.NO_WRAP);}
 static byte[] derive(String pass,byte[] salt)throws Exception{if(pass==null||pass.length()<10)throw new GeneralSecurityException("Use an unlock passphrase of at least 10 characters");PBEKeySpec spec=new PBEKeySpec(pass.toCharArray(),salt,120000,384);try{return SecretKeyFactory.getInstance("PBKDF2WithHmacSHA1").generateSecret(spec).getEncoded();}finally{spec.clearPassword();}}
 static byte[] tag(byte[] key,byte[] iv,byte[] data)throws Exception{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(Arrays.copyOfRange(key,16,48),"HmacSHA256"));mac.update(iv);return mac.doFinal(data);}
 static String seal(Context context,String server,String token,String pass)throws Exception{SecureRandom random=new SecureRandom();byte[] key=new byte[48],iv=new byte[16],salt=new byte[16];random.nextBytes(iv);random.nextBytes(salt);JSONObject blob=new JSONObject();if(Build.VERSION.SDK_INT>=18){random.nextBytes(key);blob.put("mode","keystore");blob.put("wrapped",b64(Api18.wrap(context,key)));}else{key=derive(pass,salt);blob.put("mode","passphrase");blob.put("salt",b64(salt));}try{JSONObject value=new JSONObject();value.put("server",server);value.put("token",token);Cipher cipher=Cipher.getInstance("AES/CBC/PKCS5Padding");cipher.init(Cipher.ENCRYPT_MODE,new SecretKeySpec(Arrays.copyOf(key,16),"AES"),new IvParameterSpec(iv));byte[] data=cipher.doFinal(value.toString().getBytes("UTF-8"));blob.put("iv",b64(iv));blob.put("data",b64(data));blob.put("mac",b64(tag(key,iv,data)));return blob.toString();}finally{Arrays.fill(key,(byte)0);}}
 static JSONObject open(Context context,String saved,String pass)throws Exception{JSONObject blob=new JSONObject(saved);byte[] key;if(blob.getString("mode").equals("keystore")){if(Build.VERSION.SDK_INT<18)throw new GeneralSecurityException("Keystore unavailable on this Android version");key=Api18.unwrap(bytes(blob,"wrapped"));}else key=derive(pass,bytes(blob,"salt"));try{byte[] iv=bytes(blob,"iv"),data=bytes(blob,"data");if(key.length!=48||!MessageDigest.isEqual(tag(key,iv,data),bytes(blob,"mac")))throw new GeneralSecurityException("Cannot unlock saved session");Cipher cipher=Cipher.getInstance("AES/CBC/PKCS5Padding");cipher.init(Cipher.DECRYPT_MODE,new SecretKeySpec(Arrays.copyOf(key,16),"AES"),new IvParameterSpec(iv));return new JSONObject(new String(cipher.doFinal(data),"UTF-8"));}finally{Arrays.fill(key,(byte)0);}}
 static class Api18 {
 static KeyStore store()throws Exception{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);return ks;}
 static byte[] wrap(Context c,byte[] key)throws Exception{KeyStore ks=store();if(!ks.containsAlias(ALIAS)){Calendar begin=Calendar.getInstance(),end=Calendar.getInstance();end.add(Calendar.YEAR,25);android.security.KeyPairGeneratorSpec spec=new android.security.KeyPairGeneratorSpec.Builder(c).setAlias(ALIAS).setSubject(new javax.security.auth.x500.X500Principal("CN=Sky Family Immich")).setSerialNumber(java.math.BigInteger.ONE).setStartDate(begin.getTime()).setEndDate(end.getTime()).build();KeyPairGenerator gen=KeyPairGenerator.getInstance("RSA","AndroidKeyStore");gen.initialize(spec);gen.generateKeyPair();ks=store();}Cipher cipher=Cipher.getInstance("RSA/ECB/PKCS1Padding");cipher.init(Cipher.ENCRYPT_MODE,ks.getCertificate(ALIAS).getPublicKey());return cipher.doFinal(key);}
 static byte[] unwrap(byte[] wrapped)throws Exception{KeyStore.PrivateKeyEntry entry=(KeyStore.PrivateKeyEntry)store().getEntry(ALIAS,null);if(entry==null)throw new GeneralSecurityException("Saved device key is unavailable; sign in again");Cipher cipher=Cipher.getInstance("RSA/ECB/PKCS1Padding");cipher.init(Cipher.DECRYPT_MODE,entry.getPrivateKey());return cipher.doFinal(wrapped);}
 }
}
